/* Pixel-themed palette: deep navy, teal, amber, off-white */
:root {
  --bg: #1a1c2c;
  --card-bg: #2a2e4a;
  --accent: #6ac6c6;
  --highlight: #f0c674;
  --text: #e8e8f0;
  --border: #4a4e6a;
  --focus: #f0c674;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
  background-image: 
    linear-gradient(45deg, var(--border) 25%, transparent 25%),
    linear-gradient(-45deg, var(--border) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--border) 75%),
    linear-gradient(-45deg, transparent 75%, var(--border) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  background-color: var(--bg);
}

.card {
  background: var(--card-bg);
  border: 3px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 var(--border);
}

h1 {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 24px;
  text-align: center;
  text-shadow: 2px 2px 0 var(--border);
}

.converter {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

label {
  font-size: 16px;
  font-weight: 600;
  color: var(--highlight);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input, select {
  font-family: inherit;
  font-size: 18px;
  padding: 12px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 0;
  color: var(--text);
  width: 100%;
  transition: border-color 0.1s, box-shadow 0.1s;
}

input:focus, select:focus {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--accent);
}

input:hover, select:hover {
  border-color: var(--accent);
}

input:active, select:active {
  border-color: var(--highlight);
}

.row {
  display: flex;
  align-items: flex-end;
  gap: 12px;
}

#swap {
  font-size: 24px;
  padding: 8px 12px;
  background: var(--accent);
  color: var(--bg);
  border: 2px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  line-height: 1;
  transition: background 0.1s, transform 0.1s;
  flex-shrink: 0;
  margin-bottom: 2px;
}

#swap:hover {
  background: var(--highlight);
  border-color: var(--highlight);
}

#swap:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

#swap:active {
  transform: translate(2px, 2px);
  background: var(--highlight);
}

.result {
  font-size: 36px;
  font-weight: 700;
  text-align: right;
  padding: 16px;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--highlight);
  letter-spacing: 1px;
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  word-break: break-all;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 20px;
  }
  .result {
    font-size: 28px;
    padding: 12px;
  }
  .row {
    flex-direction: column;
    align-items: stretch;
  }
  #swap {
    align-self: center;
    margin-bottom: 0;
  }
}

// Fixed exchange rates relative to USD (1 USD = rate)
const RATES = {
  USD: 1,
  EUR: 0.92,
  JPY: 150.0,
  CNY: 7.2
};

const amountInput = document.getElementById('amount');
const fromSelect = document.getElementById('from');
const toSelect = document.getElementById('to');
const swapBtn = document.getElementById('swap');
const resultEl = document.getElementById('result');

function convert() {
  const amount = parseFloat(amountInput.value);
  if (isNaN(amount) || amount < 0) {
    resultEl.textContent = '0.00';
    return;
  }
  const from = fromSelect.value;
  const to = toSelect.value;
  const fromRate = RATES[from];
  const toRate = RATES[to];
  if (!fromRate || !toRate) {
    resultEl.textContent = '0.00';
    return;
  }
  const converted = (amount / fromRate) * toRate;
  // Round to two decimals using integer cents to avoid floating point issues
  const cents = Math.round(converted * 100);
  resultEl.textContent = (cents / 100).toFixed(2);
}

function swapCurrencies() {
  const fromVal = fromSelect.value;
  fromSelect.value = toSelect.value;
  toSelect.value = fromVal;
  convert();
}

amountInput.addEventListener('input', convert);
fromSelect.addEventListener('change', convert);
toSelect.addEventListener('change', convert);
swapBtn.addEventListener('click', swapCurrencies);

// Initial conversion
convert();
